__d(function(g,r,i,a,m,_e,d){"use strict";function e(e){return e&&e.__esModule?e:{default:e}}Object.defineProperty(_e,'__esModule',{value:!0}),Object.defineProperty(_e,"default",{enumerable:!0,get:function(){return z}});var o=r(d[0]);r(d[1]);var t=e(r(d[2])),n=e(r(d[3])),s=r(d[4]),l=r(d[5]),c=r(d[6]),u=r(d[7]),p=r(d[8]);const v="Da completare prima dell\u2019attivazione del servizio con dati personali.";function z(){const{demo:e}=(0,l.useApp)(),z=[["1. Chi gestisce i dati",`Titolare del trattamento: ${c.privacyDetails.controller||v}\nSede e recapito postale: ${c.privacyDetails.address||v}\nContatto privacy: ${c.privacyDetails.email||v}\n${c.privacyDetails.dpo?`Responsabile della protezione dei dati (DPO): ${c.privacyDetails.dpo}`:"Contatto DPO: da indicare se nominato; la nomina e la sua eventuale obbligatoriet\xe0 devono essere verificate dal titolare."}`],["2. Cosa succede nella demo","Puoi esplorare senza account. Preferenze, data eventualmente scelta, letture salvate e progressi sono conservati nel browser o sul dispositivo. Non \xe8 prevista una cifratura locale dedicata: usa un dispositivo personale e rimuovi i dati se \xe8 condiviso. Cancellare i dati su un browser non cancella quelli eventualmente presenti su altri dispositivi. Registrazione e chat sono disabilitate nella demo; le conversazioni mostrate sono esempi, non messaggi inviati."],["3. Account e dati del servizio previsto","Con l\u2019attivazione dell\u2019account saranno trattati email, identificativo utente, dati di autenticazione e le preferenze che scegli di salvare, per riconoscerti e ritrovare lo stesso percorso sul sito e nell\u2019app. Le password sono gestite dal sistema di autenticazione; non sono mostrate alla professionista. Le scelte di percorso, gli argomenti e una data di gravidanza o nascita possono rivelare informazioni sulla salute. Non inserire nomi o dati di bambini, partner o altre persone se non necessari e senza averne verificato i presupposti."],["4. Finalit\xe0 e basi giuridiche","L\u2019account e la sincronizzazione, quando attivi, sono finalizzati a fornire il servizio richiesto: la base da verificare \xe8 l\u2019esecuzione del contratto o di misure precontrattuali (art. 6, par. 1, lett. b, GDPR). La personalizzazione facoltativa che utilizza dati sulla salute richiede una specifica condizione dell\u2019art. 9 GDPR e una base dell\u2019art. 6: il consenso esplicito, ove applicabile, deve essere separato, informato, dimostrabile e revocabile (artt. 6, par. 1, lett. a, e 9, par. 2, lett. a). Le basi per sicurezza, adempimenti e chat, e l\u2019eventuale distinto trattamento sanitario della professionista, devono essere definite dal titolare prima dell\u2019attivazione; non si presume che una chat educativa sia una prestazione sanitaria. Leggere l\u2019informativa o creare un account non equivale a prestare un consenso generale."],["5. Cosa \xe8 facoltativo","La consultazione come ospite non richiede email, password o una data. Per un account servono i dati di autenticazione; senza questi non \xe8 possibile accedere ai servizi personali. Puoi non fornire la data e usare un percorso generico. La rinuncia alla personalizzazione facoltativa non impedisce di leggere i contenuti. Il marketing e le notifiche push non sono attivi: non viene richiesto ora un consenso per future comunicazioni promozionali."],["6. Messaggi alla Dott.ssa Brunetti","La chat reale richieder\xe0 l\u2019accesso e l\u2019abilitazione della professionista. La gestione delle conversazioni \xe8 affidata esclusivamente alla Dott.ssa Gaia Brunetti. L\u2019utente vede la propria conversazione; la redazione non accede alle chat per il solo ruolo editoriale. Anche il gestore del servizio e i fornitori possono avere accessi tecnici nei limiti delle proprie funzioni: non \xe8 una chat con cifratura end-to-end. Evita referti, foto, dettagli sanitari o dati di terzi non necessari. La base giuridica e l\u2019eventuale gestione di dati sanitari devono essere definite prima di ricevere messaggi reali. Le risposte non sono immediate: per urgenze contatta i servizi di emergenza."],["7. Fornitori e destinatari",`Il sito dimostrativo \xe8 distribuito tramite GitHub Pages. Le richieste al sito possono comportare il trattamento di indirizzo IP, dati del browser e log tecnici da parte del fornitore. Il servizio account e la chat sono predisposti per Supabase; il pannello professionale richiede un hosting separato. Fornitori effettivi, ruoli privacy, eventuali responsabili nominati ai sensi dell\u2019art. 28 GDPR e destinatari: ${c.privacyDetails.providers||v} I dati non sono destinati alla diffusione pubblica; eventuali comunicazioni ad autorit\xe0 avvengono nei casi previsti dalla legge.`],["8. Paesi e trasferimenti",`Regioni dei servizi, eventuali accessi da paesi esterni allo SEE e relative garanzie: ${c.privacyDetails.transfers||v} Scegliere un server nell\u2019UE non esclude da solo trasferimenti o accessi extra SEE. Il titolare deve verificare la catena dei fornitori e, ove necessario, le condizioni del capo V GDPR, quali decisioni di adeguatezza o garanzie appropriate.`],["9. Quanto conserviamo i dati",`Nella demo i dati locali restano finch\xe9 li cancelli dal profilo o dal dispositivo/browser. Per il servizio reale devono essere fissati termini o criteri distinti per account, messaggi, log, eventuali prove del consenso e backup: ${c.privacyDetails.retention||v} La cancellazione tramite l\u2019app rimuove i dati applicativi attivi previsti dal servizio; non prova l\u2019eliminazione immediata da backup, log dei fornitori o documentazione professionale eventualmente soggetta a distinti obblighi. Tali casi e relativi termini devono essere chiariti prima dell\u2019attivazione.`],["10. Cookie e memoria del dispositivo","MAIA utilizza memoria locale per preferenze e progressi; con l\u2019account attivo utilizza anche strumenti tecnici per la sessione e l\u2019autenticazione. Il codice attuale non integra banner pubblicitari, profilazione pubblicitaria o strumenti di analisi del comportamento. Per strumenti strettamente necessari si applicano le condizioni dell\u2019art. 122 del Codice privacy; non serve un consenso generico al loro uso. Se saranno aggiunti tracker non necessari, dovranno restare bloccati fino al consenso, con possibilit\xe0 di rifiuto e revoca. L\u2019informativa andr\xe0 aggiornata. I link esterni si aprono su tua richiesta e portano a servizi con proprie informative."],["11. I tuoi diritti","Nei casi e nei limiti previsti dagli artt. 15\u201322 GDPR puoi chiedere accesso, rettifica, cancellazione, limitazione, portabilit\xe0 e opposizione. Puoi revocare un consenso in ogni momento, senza pregiudicare la liceit\xe0 del trattamento precedente. Dal profilo puoi modificare le preferenze, ritirare il consenso alla data, esportare i dati disponibili e cancellare dati locali o account. Puoi inoltre contattare il titolare: queste funzioni non sostituiscono tutti i diritti. La risposta \xe8 normalmente dovuta entro un mese; eventuali proroghe motivate sono comunicate nei termini dell\u2019art. 12 GDPR. Puoi proporre reclamo al Garante per la protezione dei dati personali e ricorrere all\u2019autorit\xe0 giudiziaria."],["12. Personalizzazione, minori e aggiornamenti","I suggerimenti sono selezionati in base alle preferenze e non prendono decisioni con effetti giuridici o analogamente significativi ai sensi dell\u2019art. 22 GDPR. MAIA non \xe8 progettata per raccogliere account di bambini o dati identificativi del neonato. Per utenti minorenni, eventuali servizi sanitari e relativi consensi occorre verificare le regole applicabili prima dell\u2019attivazione; non si presume una soglia di et\xe0 unica per tutti i trattamenti. Versione del testo: 22 ottobre 2026. Il testo deve essere aggiornato se cambiano servizi, fornitori o finalit\xe0."]];return(0,p.jsx)(u.Screen,{back:!0,title:"Privacy e dati personali",subtitle:"Le informazioni che ti servono per scegliere cosa condividere.",children:(0,p.jsxs)(n.default,{style:{width:"100%",maxWidth:760,alignSelf:"center"},children:[(0,p.jsx)(u.Notice,{icon:"lock",children:e?"Stai usando la demo: i dati delle tue scelte restano su questo dispositivo. Account e invio di messaggi non sono attivi.":"Stai usando il servizio con un backend configurato. Le informazioni seguenti devono corrispondere alla sua configurazione effettiva."}),!c.privacyComplete&&(0,p.jsx)(u.Notice,{warm:!0,children:"Informativa in completamento. I dati del titolare, i recapiti e le condizioni del servizio reale non sono ancora tutti definiti. Le sezioni sul servizio futuro non costituiscono un\u2019informativa definitiva per la sua attivazione."}),(0,p.jsx)(n.default,{style:{gap:28,marginVertical:28},children:z.map(([e,t])=>(0,p.jsxs)(n.default,{style:{gap:12},children:[(0,p.jsx)(o.Text,{accessibilityRole:"header",style:u.ui.heading,children:e}),(0,p.jsx)(o.Text,{selectable:!0,style:u.ui.body,children:t})]},e))}),c.privacyDetails.email&&(0,p.jsx)(u.Button,{variant:"secondary",onPress:()=>{t.default.openURL(`mailto:${c.privacyDetails.email}`)},children:"Contatta il titolare per la privacy"}),(0,p.jsx)(u.Button,{variant:"secondary",onPress:()=>s.router.push("/(tabs)/profile"),children:"Gestisci preferenze e dati"}),(0,p.jsx)(u.Button,{variant:"quiet",onPress:()=>{t.default.openURL("https://eur-lex.europa.eu/eli/reg/2016/679/oj/ita")},children:"Regolamento europeo sulla protezione dei dati"}),(0,p.jsx)(u.Button,{variant:"quiet",onPress:()=>{t.default.openURL("https://www.garanteprivacy.it/codice")},children:"Codice italiano in materia di protezione dei dati"}),(0,p.jsx)(u.Button,{variant:"quiet",onPress:()=>{t.default.openURL("https://www.garanteprivacy.it/")},children:"Garante: informazioni e tutela dei tuoi diritti"})]})})}},762,[768,12,221,109,766,769,807,770,6]);
